export function followUp(memory) {
  const excerpt = memory.length > 90 ? memory.slice(0, 87).trimEnd() + '…' : memory;
  return 'Du skrev «' + excerpt + '». ' + questions[2];
}

export function createDraft(answers) {
  return [answers[0], [answers[1], answers[2]].filter(Boolean).join(' '), answers[3], ...answers.slice(5)]
    .filter(Boolean).join('\n\n');
}

