export function recommend(format, audience) {
  if (format === 'pdf') return null;
  if (/besteforeldr|familien|venner|flere|og med/i.test(audience)) {
    return { label: 'Et ekstra eksemplar', reason: 'Du skrev at du vil dele boka med flere.', price: format === 'hard' ? 299 : 219 };
  }
  return { label: 'Digital PDF-kopi', reason: 'Lagre en digital kopi av den trykte boka.', price: 49 };
}

