// Preview pages use a reading-friendly text budget. Print pagination is separate.
export function bookPages(text, photos) {
  const pages = [];
  let paragraphs = [];
  let remaining = 420;

  function finishPage() {
    if (paragraphs.length) pages.push({ paragraphs });
    paragraphs = [];
    remaining = 420;
  }

  for (const paragraph of text.trim().split(/\n+/)) {
    let fragment = '';
    for (const word of paragraph.trim().split(/\s+/).filter(Boolean)) {
      // Handle an unusually long unbroken string without clipping the page.
      const chunks = word.match(/.{1,400}/gu);
      for (const [part, chunk] of chunks.entries()) {
        if (fragment.length + chunk.length + Number(part === 0) > remaining) {
          if (fragment) paragraphs.push(fragment);
          finishPage();
          fragment = '';
        }
        fragment += (fragment && part === 0 ? ' ' : '') + chunk;
      }
    }
    if (fragment) {
      paragraphs.push(fragment);
      remaining -= fragment.length + 24;
    }
  }
  finishPage();

  // Mix photos with the story while preserving each sequence's order.
  const textPages = pages.length;
  photos.forEach((photo, i) => {
    const slot = Math.ceil((i + 1) * textPages / photos.length) + i;
    pages.splice(slot, 0, { photo });
  });
  return pages;
}

