export function originalPregnancyBook(text = '', photos = [], answers = [], fields = {}, placement = {}, photoPages = []) {
  const pages = Array.from({ length: originalBookPageCount }, (_, i) => ({ artwork: i + 2 }));
  for (const [artwork, labels] of Object.entries(originalPageLabels)) pages[artwork - 2].labels = labels;
  const parentsPhoto = fields.parentsPhotoAddon === 'yes' ? { artwork: parentsPhotoAddon.art } : null;
  const withMeetingAddon = fields.meetingAddon === 'yes';
  const insertPages = withMeetingAddon ? meetingAddon.art.map(artwork => ({ artwork })) : [];
  const birthPages = fields.birthAddon === 'yes' ? birthAddon.art.map(artwork => ({ artwork })) : [];
  const artworkPages = new Map([...pages, ...(parentsPhoto ? [parentsPhoto] : []), ...insertPages, ...birthPages].map(page => [page.artwork, page]));
  for (const field of originalBookFields) {
    const page = artworkPages.get(field.artwork);
    if (!page) continue;
    const value = fields[field.key];
    if (field.slot !== undefined) {
      if ([3, 4, 10, 15, 17, 19, meetingAddon.art[1], 32, 33].includes(field.artwork)) {
        (page.photoFrames ??= []).push({ slot: field.slot, photo: photos[field.slot], box: field.box });
      } else {
        page.photoSlot = field.slot;
        page.photo = photos[field.slot];
        page.photoBox = field.box;
      }
    } else if (field.options && field.options.includes(value)) {
      (page.marks ??= []).push({ symbol: field.symbol, point: field.points[field.options.indexOf(value)],
        label: field.question + ' – ' + value });
    }
  }
  const values = { ...fields, letter: fields.letter?.trim() || text, news: fields.news ?? answers[0] };
  const slots = originalBookFields.filter(field => field.max);
  for (const slot of slots) {
    const source = placement[slot.key] ?? slot.key;
    const value = values[source] ?? '';
    const page = artworkPages.get(slot.artwork);
    if (page) (page.fields ??= []).push({ ...slot, source, value });
  }
  if (parentsPhoto) pages.splice(4, 0, parentsPhoto);
  pages.splice(5 + Number(Boolean(parentsPhoto)), 0, ...insertPages);
  pages.splice(pages.findIndex(page => page.artwork === 24) + 1, 0, ...birthPages);
  return pages.flatMap(page => [
    page,
    ...photoPages.flatMap(({ after, count }, i) => {
      if (page.artwork !== after) return [];
      const boxes = {
        1: [[63, 120, 762, 1010]],
        2: [[63, 96, 762, 501], [63, 650, 762, 501]],
        4: [[63, 160, 365, 445], [460, 160, 365, 445], [63, 645, 365, 445], [460, 645, 365, 445]]
      }[count];
      return [{
        artwork: 34,
        photoFrames: photoPageSlots(i, count).map((slot, j) => ({ slot, photo: photos[slot], box: at(...boxes[j]) }))
      }];
    })
  ]);
}

const at = (x, y, width, height) => [x / 8.88, y / 12.5, width / 8.88, height / 12.5];
const textField = (key, artwork, question, box, max = 220) => ({ key, artwork, question, box, max });
const photoField = (key, artwork, question, box, slot) => ({ key, artwork, question, box, slot });

function linedField(key, artwork, question, coords, max, pitch) {
  return { ...textField(key, artwork, question, at(...coords), max), pitch };
}

function parentFields(artwork, person, slot) {
  const mother = artwork === 3;
  const secondSlot = mother ? 11 : 12;
  return [
    linedField(person + '-minne', artwork, 'Hvordan er ' + person + 'en til barnet?', [45, 345, 790, 185], 420, 37),
    linedField(person + '-ord', artwork, 'Beskriv ' + (mother ? 'henne' : 'ham') + ' med tre ord', [128, 1049, 666, 142], 75, 49),
    photoField(person + '-foto', artwork, 'Bilde 1 av ' + person + 'en', at(36, mother ? 594 : 590, 389, 354), slot),
    photoField(person + '-foto-2', artwork, 'Bilde 2 av ' + person + 'en', at(455, mother ? 594 : 590, 384, 354), secondSlot)
  ];
}

