function choiceFields(artwork, legacyPage, labels, options, columns, rows, symbol) {
  return labels.map((question, i) => ({
    key: legacyPage + '-' + i, artwork, question, options, symbol,
    points: columns.map(x => at(x, rows[i], 0, 0).slice(0, 2))
  }));
}

